pub unsafe extern "C" fn graph2_poses_get(p: *mut Graph2Handle, r: u32) -> *mut Pose2 {
    let m = &mut (*p).model.poses;
    &mut m[arael::refs::Ref::from_raw(r)] as *mut Pose2
}
/// True while `r` addresses a live element of this collection.
#[no_mangle]
pub unsafe extern "C" fn graph2_poses_contains(p: *const Graph2Handle, r: u32) -> bool {
    (*p).model.poses.contains_ref(arael::refs::Ref::from_raw(r))
}
/// Like get, but null for a stale or foreign ref instead of a panic.
#[no_mangle]
pub unsafe extern "C" fn graph2_poses_try_get(p: *mut Graph2Handle, r: u32) -> *mut Pose2 {
    let m = &mut (*p).model.poses;
    match m.get_mut(arael::refs::Ref::from_raw(r)) {
        Some(e) => e as *mut Pose2,
        None => std::ptr::null_mut(),
    }
}
